// ─── Robust Path Resolution ─────────────────────────────────────────────────

function getRepoRootForVideoOrchestratorSpecs(): string {
  let current = process.cwd();
  for (let i = 0; i < 6; i += 1) {
    const examplePath = path.join(current, "operations", "specs", "video-orchestrator", "examples", "renderer-preflight.example.json");
    if (fs.existsSync(examplePath)) {
      return current;
    }
    const parent = path.dirname(current);
    if (parent === current) break;
    current = parent;
  }
  throw new Error("Could not locate repo root for video orchestrator specs");
}

// ─── Test Isolation ─────────────────────────────────────────────────────────

function setupTestRuntime(): string {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "probot-test-"));
  process.env.PROBOT_VIDEO_ORCHESTRATOR_RUNTIME_DIR = tempDir;
  return tempDir;
}

function cleanupTestRuntime(tempDir: string): void {
  delete process.env.PROBOT_VIDEO_ORCHESTRATOR_RUNTIME_DIR;
  try {
    fs.rmSync(tempDir, { recursive: true, force: true });
  } catch (err) {
    // Ignore cleanup errors
  }
}

